INSERT INTO public.local_register_records
  (id, register_id, display_id, title, description, status, field_values, account_id, project_id, record_project_id)
SELECT '00000000-0000-4000-a03f-000000000001'::uuid, '00000000-0000-4000-9001-00000000003f'::uuid, '',
       'Testing Strategy – Core Banking Replacement (Release 1)',
       'How the new core banking platform, its parameterisation, interfaces and migrated data are tested for Release 1: levels, phases, environments, data, tools, criteria, defect management, roles and sign-off.',
       'draft', $j${"document_reference":"TS-STR-001","document_version":"1.0","document_owner":"Maria Fernandes","next_review_date":"2027-01-31","test_manager":"Maria Fernandes","testing_start":"2026-09-01","testing_end":"2027-04-30","project_summary":"Northbridge Bank is replacing its two legacy core banking instances (retail and SME; corporate and treasury) with a single new core banking platform, Release 1 going live over the weekend of 9–12 April 2027.\n\nThis strategy sets out how the new platform, its parameterisation, its interfaces and the migrated data are tested so that the bank can go live with confidence.","purpose":"To define the testing approach, levels, environments, data, tools, roles, criteria and governance for Release 1 so that every party knows what will be tested, how, by whom and when.","objectives":"Confirm the platform is configured (parameterised) as designed for every product in scope\nProve end-to-end business processes across the core platform and its interfaces\nProve performance, failover and security meet the agreed targets\nSupport the business through user acceptance testing and obtain sign-off\nRehearse the go-live weekend and confirm timings\nExit with no open critical or high defects","scope":"Core banking platform – Release 1 (deposits, lending, payments, trade finance, treasury)\nInterfaces to channels, payments, cards and finance\nMigrated data (with the data migration workstream)\nReports and statements","testing_services":"Test strategy and planning\nFunctional test design and execution\nTest automation of the regression pack\nNon-functional testing (performance, failover, security)\nUAT support\nDress rehearsal support\nDefect management and reporting","functional_scope":"Customer\tOnboarding, KYC, relationships, maintenance\tHigh\nAccounts\tOpening, maintenance, interest, charges, dormancy, closure\tHigh\nDeposits\tFixed and call deposits, rollover, maturity\tHigh\nLending\tDisbursement, schedules, repayments, arrears, restructuring\tHigh\nPayments\tInternal and external transfers, standing orders, real-time payments\tHigh\nTrade finance\tLetters of credit, guarantees, bills\tMedium\nTreasury\tFX and money market deals\tMedium\nGeneral ledger\tClose of business, accounting entries, reports\tHigh","out_of_scope":"Decommissioning of the legacy systems\nCard management system internals (interface only)\nRelease 2 products","assumptions":"Environments are delivered on the agreed dates\nBusiness testers are released for UAT\nTest data is masked before use outside production","constraints":"UAT must finish before the first dress rehearsal\nProduction-sized data only in pre-production","test_approach":"Risk-based, phase-by-phase approach: each phase must meet its exit criteria before the next starts. Parameterisation and sanity testing confirm the build; system and integration testing prove functions and end-to-end flows; non-functional testing and UAT run in parallel where environments allow; dress rehearsals prove the go-live.","test_levels":["parameterisation","sanity","system","integration_sit","user_acceptance","regression","performance","failover","security","migration","interface"],"risk_based_testing":true,"test_techniques":"Requirements-based test design\nBoundary values and equivalence classes\nEnd-to-end business scenarios\nExploratory testing sessions\nAutomated regression","functional_test_design":"Test cases are written from the approved business requirements and configuration documents, one test set per module, traced to requirements in the test management tool. End-to-end scenarios follow a customer journey across modules and interfaces.","automated_test_design":"The regression pack (about 600 high-risk scenarios) is automated and run after every build drop and before each dress rehearsal. Data-driven scripts reuse the masked test data sets.","test_phases":"Parameterisation testing\tConfiguration matches the design\tTest\t2026-09-01\t2026-09-30\tTest manager\nSanity testing\tBuild is stable enough to test\tSIT\t2026-10-01\t2026-10-03\tTest lead\nSystem testing\tEach module works as specified\tSIT\t2026-10-05\t2026-11-27\tTest lead\nSystem integration testing\tEnd-to-end flows across interfaces\tSIT\t2026-11-30\t2027-01-29\tIntegration test lead\nUser acceptance testing\tBusiness accepts the solution\tUAT\t2027-02-01\t2027-03-05\tUAT lead\nDress rehearsals\tGo-live weekend proven\tPre-production\t2027-02-13\t2027-03-21\tCutover manager","parameterisation_testing":"Every product, charge, interest and accounting parameter is checked against the configuration documents by the business analysts, using parameter reports from the platform. Differences are logged as defects before system testing starts.","sanity_testing":"A short set of smoke tests (log in, create customer, open account, post a transaction, run close of business) after every new build or environment refresh decides whether the build is accepted for testing.","system_testing":"Module-by-module functional testing of the core banking platform against the requirements: customer, accounts, deposits, lending, payments, trade finance, treasury and the general ledger, including close-of-business processing.","integration_testing":"End-to-end testing of business flows through the core platform and its interfaces: channels, payment switch, cards, finance, anti-money-laundering monitoring and reporting.","performance_testing":"Load and stress tests in pre-production with production-sized volumes: peak online transactions, batch close of business, and month-end processing.","performance_targets":"Teller transaction\t120 per second\tUnder 2 seconds\t95th percentile response\nInternet banking login\t300 per minute\tUnder 3 seconds\t95th percentile response\nClose of business\tFull volumes\tUnder 3 hours\tBatch duration\nMonth-end close of business\tFull volumes\tUnder 5 hours\tBatch duration","failover_testing":"Planned switch from the primary to the secondary data centre during online hours and during close of business, proving recovery time and recovery point objectives.","security_testing":"Penetration testing of the platform and interfaces by an independent tester, user role and segregation-of-duties checks, and encryption of data in transit and at rest.","uat_support":"The testing team prepares the UAT environment and data, trains business testers, provides daily triage of defects and reports progress to the business sign-off board.","uat_participants":"Retail banking\nBusiness banking\nCorporate banking\nCredit operations\nTreasury operations\nFinance\nPayments operations","dress_rehearsal":"Three timed rehearsals of the go-live runbook in pre-production, covering technical cutover, data migration, reconciliation and business verification, with go / no-go decision points.","dress_rehearsals_planned":"Dress rehearsal 1\t2027-02-13\tStatic window\nDress rehearsal 2\t2027-03-06\tFinancial window\nDress rehearsal 3\t2027-03-20\tFinal timed rehearsal with business sign-off","test_environments":["test","sit","uat","pre_production","dr"],"test_data_approach":"Masked copies of production data for SIT and UAT, plus synthetic data for edge cases. Migrated data from the mock migrations is used for UAT so business testers see real products and balances.","data_masking_required":true,"entry_criteria":"Test plan approved\nEnvironment available and sanity-tested\nTest cases reviewed\nNo open critical defects from the previous phase","exit_criteria":"All planned tests executed\n95% of tests passed\nNo open critical or high defects\nTest summary report approved","suspension_criteria":"Environment unavailable for more than four hours\nA critical defect blocks more than 30% of tests","resumption_criteria":"Environment restored and sanity-tested\nBlocking defect fixed and retested","acceptance_criteria":"Business processes in scope work end to end\nPerformance targets met\nReconciled migrated data accepted by data owners\nSigned UAT acceptance from each business unit","critical_success_factors":"Stable environments on time\nBusiness testers available\nFast defect turnaround from the vendor and partner\nClear requirements and configuration documents","severity_definitions":"Critical – system unusable or financial impact, no workaround\nHigh – major function fails, workaround difficult\nMedium – function fails, workaround exists\nLow – cosmetic or minor","defect_workflow":"New → Triaged → Assigned → Fixed → Ready for retest → Closed (or Reopened). Daily triage with the vendor and partner; severity agreed by the test manager and business owner.","defect_resolution_targets":"Critical\t2 hours\t1 day\nHigh\t4 hours\t3 days\nMedium\t1 day\t5 days\nLow\t2 days\tNext release","acceptable_open_defects_at_exit":"Critical: none\nHigh: none\nMedium: up to 10 with agreed workarounds\nLow: no limit, with a fix plan","document_management":"All test documents stored in the project document library\nVersion control on plans, cases and reports\nApproved documents read-only","meetings":"Daily defect triage\tDaily\tTest leads, vendor, partner\tAgree severity and fixes\nWeekly test status\tWeekly\tTest manager, project manager, business leads\tProgress, risks, decisions\nPhase exit review\tPer phase\tSign-off board\tApprove phase exit","reporting_cadence":"weekly","metrics_reported":"Test execution progress (planned vs executed vs passed)\nOpen defects by severity and age\nRequirement coverage\nEnvironment availability","test_deliverables":"Test strategy\nTest plans per phase\nTest cases and scripts\nDaily and weekly reports\nTest summary report per phase\nUAT sign-off","signoff_board":"Test strategy\tTest manager\tProgramme director\nPhase test summary reports\tBusiness leads\tProgramme director\nUAT acceptance\tBusiness unit heads\tExecutive sponsor","test_management_tool":"Test management tool (requirements, test cases, execution and defects in one place)","testing_tools":"Test management tool\tTest cases, execution, defects, reports\t45 users\nAutomation tool\tRegression automation\t4 licences\nPerformance test tool\tLoad and stress tests\t1 licence\nData masking tool\tMasking test data\tTesting team","automation_approach":"Automate stable, high-risk regression scenarios first; keep new functions manual until stable; run the automated pack after every build drop.","test_timeline":"Parameterisation testing\t2026-09-01\t2026-09-30\t\nSystem testing\t2026-10-05\t2026-11-27\t\nSystem integration testing\t2026-11-30\t2027-01-29\t\nUser acceptance testing\t2027-02-01\t2027-03-05\t\nDress rehearsals\t2027-02-13\t2027-03-21\tThree rehearsals\nGo-live\t2027-04-09\t2027-04-12\tGo-live weekend","raci":"Test strategy\tTest manager\tProgramme director\tBusiness leads\tSteering committee\nTest execution\tTesters\tTest manager\tVendor\tProject manager\nDefect fixing\tVendor / partner\tProject manager\tTest manager\tBusiness leads\nUAT\tBusiness testers\tBusiness unit heads\tTest manager\tSteering committee\nGo-live sign-off\tProgramme director\tExecutive sponsor\tBusiness unit heads\tRegulator (as required)","risks_mitigations":"Environments late\tTesting compressed\tTrack dates weekly with IT\tRun phases in parallel where possible\nBusiness testers not released\tUAT delayed\tAgree release letters with heads of department\tExtend UAT by one week\nHigh defect volumes\tExit criteria missed\tDaily triage and fix targets\tDefer low-priority fixes\nUnstable builds\tLost testing time\tSanity test every build\tRoll back to the last good build","roles_and_responsibilities":"Test manager\tMaria Fernandes\tNorthbridge Bank\tStrategy, planning, reporting, sign-off\nTest lead\tTest lead\tTesting partner\tTest design and execution\nAutomation engineer\tAutomation engineer\tTesting partner\tRegression automation\nPerformance tester\tPerformance tester\tTesting partner\tLoad, stress and failover tests\nUAT lead\tAmina Diallo\tNorthbridge Bank\tBusiness testers and UAT sign-off","acronyms":"CoB\tClose of business\nSIT\tSystem integration testing\nUAT\tUser acceptance testing\nRTO\tRecovery time objective\nRPO\tRecovery point objective\nRACI\tResponsible, accountable, consulted, informed","glossary":"Dress rehearsal\tFull, timed run of the go-live steps in a production-like environment\nRegression pack\tSet of tests re-run to confirm nothing that worked before is broken\nSanity test\tShort check that a new build is stable enough to test","appendices":"Appendix 1 – Test plan per phase\tTS-PLN-001\nAppendix 2 – Requirements traceability matrix\tTS-RTM-001\nAppendix 3 – UAT sign-off form\tTS-UAT-001","version_history":"0.1\t2026-07-15\tMaria Fernandes\tFirst draft\n1.0\t2026-08-28\tMaria Fernandes\tBaseline for approval","related_documents":"Data Migration Strategy (LREG-2026-105)\nCutover Strategy\nBusiness requirements documents\nConfiguration documents"}$j$::jsonb, p.account_id, p.id, p.id
FROM public.projects p
WHERE p.project_code = 'SEED334-PRJ-08'
ON CONFLICT (id) DO NOTHING;

